import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosBox, KozmosGrid } from "../../index";

/**
 * Vue's Grid: the stories React's has, with the same names and args, each
 * inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. React's draw their items as JSX, so each is drawn here as React's
 * draws it, from KozmosBox; test/parity/grid.parity.spec.ts holds Vue's
 * render to React's. Generated by `port Grid`, then drawn by hand.
 */
type Args = Record<string, unknown>;

/** React's Item: a centred cell on the theme fill. */
const ITEM_CLASS =
  "p-4 bg-theme-fill text-theme-fill-foreground rounded flex items-center justify-center";

const meta: Meta<Args> = {
  title: "Vue/Core/Layout/Grid",
  component: KozmosGrid,
  argTypes: {
    cols: { control: "select", options: [1, 2, 3, 4, 6, 12, "none"] },
    gap: { control: "select", options: [0, 1, 2, 4, 8] },
  },
};

export default meta;
type Story = StoryObj<Args>;

/** React's Default: six items in three columns, 16 apart. */
export const Default: Story = {
  args: { cols: 3, gap: 4 },
  render: (args) => ({
    components: { KozmosBox, KozmosGrid },
    setup: () => ({ args, items: [1, 2, 3, 4, 5, 6], itemClass: ITEM_CLASS }),
    template: `
      <KozmosGrid v-bind="args">
        <KozmosBox v-for="item in items" :key="item" :class="itemClass">{{ item }}</KozmosBox>
      </KozmosGrid>
    `,
  }),
};

/**
 * GAP-172 (decision 209): Home's hundreds of site cards. Only the rows in
 * view and two past them are drawn, in reading order, each said as its place
 * in the 300; the Grid scrolls itself, so it has a height.
 * Drawn with a render function, not a template, so its text is React's to the
 * node: a template keeps the spaces around a line's words and joins words
 * React draws as separate text nodes (test/parity/story-renders.parity.spec.ts).
 */
export const Virtualized: Story = {
  args: {
    virtualized: true,
    cols: 3,
    gap: 4,
    itemCount: 300,
    rowHeight: 72,
    "aria-label": "Sites",
    style: { height: "320px" },
  },
  render: (args) => ({
    setup: () => () =>
      h(KozmosGrid, args, {
        renderItem: ({ index }: { index: number }) =>
          h(KozmosBox, { class: ITEM_CLASS }, () => [
            "Site ",
            String(index + 1),
          ]),
      }),
  }),
};
